mapper.select:
SELECT noti_id, group_id, noti_title, noti_writer, DATE_FORMAT(noti_created_at, '%Y-%m-%d %H:%i:%s') AS noti_created_at, DATE_FORMAT(noti_updated_at, '%Y-%m-%d %H:%i:%s') AS noti_updated_at FROM smartbusmngdb.sbm_mybus_notice
group_id = #{groupId}
AND
noti_title LIKE CONCAT('%', #{keyword}, '%')
ORDER BY noti_id DESC LIMIT #{size} OFFSET #{offset}

mapper.delete:
DELETE FROM smartbusmngdb.sbm_mybus_notice
WHERE noti_id = #{notiId}
  AND group_id = #{groupId}
